<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?= htmlspecialchars($vendor['name']) ?> | Lokal Culture</title><link rel="stylesheet" href="/assets/css/app.css"><link rel="stylesheet" href="/assets/css/catalog.css"></head>
<body><header class="site-header"><a class="brand" href="/">✦ LOKAL <em>CULTURE</em></a><nav class="header-actions"><a href="/shop">Shop</a><a href="/account">Account</a></nav></header><main class="vendor-shell"><p class="eyebrow">Independent maker</p><h1><?= htmlspecialchars($vendor['name']) ?></h1><p class="vendor-description"><?= htmlspecialchars($vendor['description']) ?></p><?php if (!empty($vendor['region']) || !empty($vendor['craft_specialty'])): ?><p class="vendor-description"><?= htmlspecialchars($vendor['region'] ?? '') ?><?= !empty($vendor['region']) && !empty($vendor['craft_specialty']) ? ' · ' : '' ?><?= htmlspecialchars($vendor['craft_specialty'] ?? '') ?></p><?php endif; ?><div class="vendor-products"><?php foreach ($vendor['products'] as $product): ?><article class="catalog-card"><a href="/product/<?= urlencode($product['slug']) ?>"><div class="catalog-image"><img loading="lazy" src="<?= htmlspecialchars($product['image']) ?>" alt="<?= htmlspecialchars($product['name']) ?>"></div><p><?= htmlspecialchars($product['category']) ?></p><h2><?= htmlspecialchars($product['name']) ?></h2><strong><?= htmlspecialchars($product['price']) ?></strong></a></article><?php endforeach; ?></div></main></body></html>